package io.aetheris.orchestrator.evaluation;
import org.springframework.stereotype.Service;import java.util.*;
@Service public class EvaluationService {private final EvaluationRunRepository repository;public EvaluationService(EvaluationRunRepository repository){this.repository=repository;}public EvaluationRunEntity record(EvaluationRequest r){if(r.subjectType()==null||r.subjectType().isBlank()||r.subjectId()==null||r.subjectId().isBlank()||r.scenario()==null||r.scenario().isBlank())throw new IllegalArgumentException("subjectType, subjectId and scenario are required");double score=(r.success()?40:0)+Math.min(30,Math.max(0,r.evidenceScore())*.30)-Math.min(20,Math.max(0,r.hallucinationPenalty())*.20)-Math.min(15,Math.max(0,r.corrections())*3.0)-Math.min(10,Math.max(0,r.costUsd())*2.0)-Math.min(10,Math.max(0,r.latencyMs()-1000)/1000.0);return repository.save(new EvaluationRunEntity(UUID.randomUUID(),r,Math.max(0,Math.min(100,score))));}public List<EvaluationRunEntity> recent(){return repository.findTop200ByOrderByCreatedAtDesc();}public double average(String type,String id){return repository.findTop100BySubjectTypeAndSubjectIdOrderByCreatedAtDesc(type,id).stream().mapToDouble(EvaluationRunEntity::getOverallScore).average().orElse(0);}}
